; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxndotl (ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen)), starts in normal mode
; ============================================================

			OUTPUT "OWNSTDIO.DOT"		; the dot command (C:/DOT/OWNSTDIO.DOT: .ownstdio at the BASIC prompt)
; ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen): NTC_ZXNDOT defined, and NTC_ZXNDOTL (the Large Model: the program from #8000, the Memory class's banks from NextZXOS's allocator - asm/ntc_lib_dot.asm)
			DEFINE NTC_ZXNDOT
			DEFINE NTC_ZXNDOTL
			org #2000

; ============================================================
; Platform start code (the platform's ntc_plat_romhead) - at the org, on to ntc_start
; ============================================================
; ------------------------------------------------------------
; The entry (the compiler puts this section first, at #2000) and the
; BASIC-side machinery: everything the ROM calls need, in one place, so
; that the Large Model (zxndotl) - which runs the program from #8000 in its
; own pages and keeps only this 8K in common with BASIC's memory - has it
; here too. Self-contained: no label from another section is named.
; ------------------------------------------------------------
dot_entry:
			di
			ld (dot_bsp), sp		; BASIC's stack: the ROM calls run on it, End returns on it
			ld (dot_hl), hl			; the arguments (0: none)
			ld (dot_bc), bc
			ld a, i
			ld (dot_iold), a		; BASIC's I (put back at the end)
			ld sp, dot_tstack		; a stack of our own for the rest of the entry
			call dot_cmdsave		; the arguments into ntc_cmdbuf before anything moves them
	IFDEF NTC_ZXNDOTL
			call dotl_setup			; the Large Model: its pages, the program read from this file
	ENDIF
			ld hl, dot_chan			; the upper screen is the channel printed to
			call dot_os
			ld a, dot_ivec >> 8		; IM 2, our handler (dot_irq) from here on, except inside dot_os
			ld i, a
			im 2
			jp ntc_start

; dot_cmdsave - (dot_hl) = the arguments: into ntc_cmdbuf, 0 ended, up to 127
; characters, up to #0D, ':' outside double quotes, or 0; leading spaces left out
dot_cmdsave:
			ld hl, (dot_hl)
			ld de, ntc_cmdbuf
			ld a, h
			or l
			jr z, dot_cs_end
			ld b, 127
			ld c, 0					; C = 1 inside quotes
dot_cs_sp:
			ld a, (hl)
			cp ' '
			jr nz, dot_cs_lp
			inc hl
			jr dot_cs_sp
dot_cs_lp:
			ld a, (hl)
			or a
			jr z, dot_cs_end
			cp #0D
			jr z, dot_cs_end
			cp '"'
			jr nz, dot_cs_nq
			ld a, c
			xor 1
			ld c, a
			ld a, '"'
dot_cs_nq:
			cp ':'
			jr nz, dot_cs_st
			bit 0, c
			jr z, dot_cs_end		; a ':' outside quotes ends the line
dot_cs_st:
			ld (de), a
			inc hl
			inc de
			djnz dot_cs_lp
dot_cs_end:
			xor a
			ld (de), a
			ret

; dot_os - HL = a routine (in this 8K) to run on BASIC's side: BASIC's stack,
; IY = ERR_NR (the ROM's), interrupts on (the ROM's keyboard scan, "scroll?"),
; and - the Large Model - BASIC's memory in slots 2-7. Back with interrupts
; off, our stack (SP as it was) and our memory; A, BC, DE, HL as the routine
; left them, IX kept. Call it on the real stack, never with SP in the thread
dot_os:
			ld (dot_osp), sp
			ld (dot_oix), ix
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack		; (the swap's calls: never on the program's stack, which is in a slot being swapped)
			push hl
			call dotl_bside			; slots 2-7 = BASIC's (ours noted)
			pop hl
	ENDIF
			ld sp, (dot_bsp)
			ld iy, #5C3A
			im 1					; the ROM's handler while the ROM runs
			ex de, hl
			ld hl, (#5C78)			; FRAMES now: its advance during the call is added to dot_frames
			ld (dot_fr0), hl
			ex de, hl
			ld de, dot_os_back
			push de
			ei
			jp (hl)
dot_os_back:
			di
			push af					; (the routine's result: A and the flags - dotl_alloc's carry)
			push hl
			push de
			ld hl, (#5C78)
			ld de, (dot_fr0)
			or a
			sbc hl, de
			ld de, (dot_frames)
			add hl, de
			ld (dot_frames), hl
			pop de
			pop hl
			pop af
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack
			push af
			push hl
			call dotl_oside			; slots 2-7 = ours again
			pop hl
			pop af
	ENDIF
			im 2
			ld sp, (dot_osp)
			ld ix, (dot_oix)
			ret

; ---- the BASIC-side routines (reached through dot_os only)
; dot_chan - the upper screen, channel 2, is the channel rst #10 prints to
dot_chan:
			ld a, 2
			rst #18
			dw #1601				; CHAN-OPEN
			ret
; dot_putc - (dot_ch) printed
dot_putc:
			ld a, (dot_ch)
			rst #10
			ret
; dot_cls - the ROM's CLS, then the channel again (CLS leaves the lower screen's)
dot_cls:
			rst #18
			dw #0D6B				; CLS
			jr dot_chan
; dot_at - AT (dot_row), (dot_col): the ROM's control code 22
dot_at:
			ld a, 22
			rst #10
			ld a, (dot_row)
			rst #10
			ld a, (dot_col)
			rst #10
			ret
; dot_wait - a frame: until the ROM's interrupt moves FRAMES on (not halt: a program
; that stops on halt can't be stepped by every harness - and the ROM's handler runs
; the same either way)
dot_wait:
			ld hl, #5C78			; FRAMES
			ld a, (hl)
dot_wt_lp:
			cp (hl)
			jr z, dot_wt_lp
			ret
; dot_kread - a frame's wait for the ROM's keyboard scan, then A = the new key
; (LAST_K, the FLAGS bit cleared) or 0
dot_kread:
			call dot_wait
			ld a, (#5C3B)			; FLAGS: bit 5 = a new key in LAST_K
			bit 5, a
			jr z, dot_kr_none
			res 5, a
			ld (#5C3B), a
			ld a, (#5C08)			; LAST_K
			ret
dot_kr_none:
			xor a
			ret

; ---- the entry's data
dot_bsp:		dw 0			; BASIC's SP at entry
dot_hl:			dw 0			; HL at entry: the arguments
dot_bc:			dw 0			; BC at entry: the whole command line
dot_osp:		dw 0			; dot_os: our SP
dot_oix:		dw 0			; dot_os: IX
dot_ch:			db 0			; the character for dot_putc
dot_row:		db 0			; dot_at: row, column (0 based)
dot_col:		db 0
dot_frames:		dw 0			; frames counted (dot_irq, plus FRAMES' advance in the ROM calls): Ticks
dot_fr0:		dw 0			; dot_os: FRAMES at the call's start
dot_iold:		db 0			; BASIC's I register
ntc_cmdbuf:		ds 128			; the arguments, 0 ended (System.CommandLine)
; dot_irq - the IM 2 handler: a frame counted. Only this 8K is touched (it runs with the
; program's memory in the slots and SP on the program's real stack)
dot_irq:
			push hl
			ld hl, (dot_frames)
			inc hl
			ld (dot_frames), hl
			pop hl
			ei
			reti
; the IM 2 vector table, 256-aligned: the Z80 reads its bytes #FF and #100 (the data bus
; gives #FF) - the handler's address; the rest is the entry's two stacks
			ALIGN 256
dot_ivec:
			ds 255 - 48
			ds 32
dot_tstack:						; the entry's own stack (32 bytes: the entry's calls only)
			ds 16
dot_xstack:						; dot_os's own (16 bytes: the slot swap's calls - the Large Model) = dot_ivec + #FF
			dw dot_irq				; the vector

	IFDEF NTC_ZXNDOTL
; ------------------------------------------------------------
; The Large Model (zxndotl): the program runs from #8000 in four 8K pages of
; its own, the Memory class's window #4000-#7FFF is two more, all allocated
; from NextZXOS (IDE_BANK through M_P3DOS) at entry and given back at the end;
; its banks (64K: 8 pages each) come from the same allocator at the Memory
; class's first call (ntc_lib_dot.asm). Slots 2-7 hold ours while the program
; runs, BASIC's while a ROM / esxDOS call runs (dot_os: dotl_bside / dotl_oside).
; The program itself is read from this file, after its first 8K (M_GETHANDLE:
; NextZXOS leaves the file open there), into #8000 on.
; ------------------------------------------------------------
DOTL_MAXPG	equ 6 + 8 * 16			; pages at most: the 6 base ones and 16 banks (1MB)
dotl_bslots:	ds 6			; BASIC's pages in slots 2-7 (NextRegs #52-#57 at entry)
dotl_oslots:	ds 6			; ours (slots 2-3 the window, 4-7 the program #8000-#FFFF), as last seen
dotl_scr:		ds 6			; (dotl_oside's reads)
dotl_npages:	db 0			; pages allocated (in dotl_pages)
dotl_pages:		ds DOTL_MAXPG	; their numbers: the 6 base ones, then the Memory class's 8 a bank
dotl_e:			db 0			; dotl_alloc: the page it got / dotl_free: the page to give back
dotl_hdl:		db 0			; this file's handle
dotl_err:		dw 0			; the message for the error return

; dotl_setup - (the entry, on dot_tstack, BASIC's memory) BASIC's slots noted, the 6
; base pages allocated and mapped, the program read into #8000 on. Doesn't return when
; it fails: the error return to BASIC with a message
dotl_setup:
			ld hl, dotl_bslots		; BASIC's pages in slots 2-7
			ld d, #52
dotl_su_rd:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)
			ld (hl), a
			inc hl
			inc d
			ld a, d
			cp #58
			jr nz, dotl_su_rd
			ld b, 6					; the 6 base pages
dotl_su_al:
			push bc
			call dotl_page			; one more into dotl_pages
			pop bc
			jr nc, dotl_su_nomem
			djnz dotl_su_al
			ld hl, dotl_pages		; ours: slots 2-3 pages 0, 1 (the window), 4-7 pages 2-5
			ld de, dotl_oslots
			ld bc, 6
			ldir
			call dotl_oside			; mapped (this 8K and the ROM stay: slots 0, 1)
			rst #08
			db #8D					; M_GETHANDLE: A = this file's handle, open after its first 8K
			ld (dotl_hdl), a
			ld hl, #8000
			ld bc, ntc_end - #8000	; the program (the file's end: no window data, no Skip on this platform)
			push bc
			rst #08
			db #9D					; F_READ: A = handle, HL = where, BC = how many
			pop hl
			jr c, dotl_su_short
			or a
			sbc hl, bc				; all of it?
			ret z
dotl_su_short:
			ld hl, dotl_m_short
			jr dotl_fail
dotl_su_nomem:
			ld hl, dotl_m_nomem
; dotl_fail - HL = the message (bit 7 on its last character): the pages back, BASIC's
; memory and stack, the esxDOS custom error return (carry set, A = 0, HL = the message)
dotl_fail:
			ld (dotl_err), hl
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld hl, (dotl_err)
			ld iy, #5C3A
			xor a
			scf
			ei
			ret
; dotl_exit - (End: ntc_plat_exit jumps here - this 8K stays mapped when slots 2-7 go
; back to BASIC's; the program's code doesn't) the pages given back, BASIC's memory and
; stack, carry clear (0 OK), interrupts on
dotl_exit:
			ld sp, dot_tstack
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld iy, #5C3A
			ld a, (dot_iold)
			ld i, a
			im 1
			or a
			ei
			ret
dotl_m_nomem:	db "Out of memory: no free 8K pages (IDE_BANK", ')' + #80
dotl_m_short:	db "The .DOT file is short: the program did not read in ful", 'l' + #80

; dotl_page - one page allocated (IDE_BANK, on BASIC's side) into dotl_pages: C = its
; number, carry set; carry clear when there is none (or no room in dotl_pages)
dotl_page:
			ld a, (dotl_npages)
			cp DOTL_MAXPG
			ret nc					; (carry clear: full)
			ld hl, dotl_alloc
			call dot_os				; carry set = got one, (dotl_e) = it
			ret nc
			ld hl, dotl_pages
			ld a, (dotl_npages)
			ld e, a
			ld d, 0
			add hl, de
			ld a, (dotl_e)
			ld (hl), a
			ld c, a
			ld a, (dotl_npages)
			inc a
			ld (dotl_npages), a
			scf
			ret
; dotl_freeall - every page in dotl_pages given back (IDE_BANK free, on BASIC's side)
dotl_freeall:
			ld a, (dotl_npages)
			or a
			ret z
			ld b, a
			ld hl, dotl_pages
dotl_fa_lp:
			ld a, (hl)
			ld (dotl_e), a
			push bc
			push hl
			ld hl, dotl_free
			call dot_os
			pop hl
			pop bc
			inc hl
			djnz dotl_fa_lp
			xor a
			ld (dotl_npages), a
			ret

; dotl_bside - slots 2-7 = BASIC's pages, ours noted first (dotl_oslots)
; dotl_oside - slots 2-7 = ours again
; (from code in this 8K, on a stack in it: slots 2-7 change under anything else)
dotl_bside:
			ld hl, dotl_oslots
			ld ix, dotl_bslots
			jr dotl_swap
dotl_oside:
			ld hl, dotl_scr
			ld ix, dotl_oslots
dotl_swap:
			ld d, #52
dotl_sw_lp:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)				; the page there now
			ld (hl), a
			ld a, (ix + 0)
			out (c), a				; the page to be
			inc hl
			inc ix
			inc d
			ld a, d
			cp #58
			jr nz, dotl_sw_lp
			ret

; ---- BASIC-side (dot_os): the allocator, M_P3DOS's IDE_BANK (#01BD): H = 0 a ZX 8K
; page, L = 1 allocate / 3 free (E = the page), the call's registers in the alternate
; set; carry SET = done, E = the page
dotl_alloc:
			ld hl, #0001
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94					; M_P3DOS
			ld a, e
			ld (dotl_e), a
			ret
dotl_free:
			ld a, (dotl_e)
			ld e, a
			ld hl, #0003
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94
			ret
	ENDIF

			ASSERT $ <= #4000, "the dot command's entry code and data must fit in #2000-#3FFF"
			ds #4000 - $			; the first 8K of the file, padded
			OPT -Wno-fileorg		; (the file goes on where the 8K ends: the org below is where the program runs, not a gap)
			org #8000			; the program: read into its own pages by the entry

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, 0		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; Main.bas 4: n = 42
			dw kw_ltov, 42, var_n

			; Main.bas 5: Print "hello"; n, "x"
			dw p_stdio_putstr_c, str0
			dw kw_strcstr, stmp0, var_n
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_putstr_c, str2
			dw p_stdio_newline_c

			; Main.bas 6: Cls
			dw p_stdio_cls_c

			; Main.bas 7: Locate 3, 4
			dw p_stdio_locate_c, lit_3, lit_4

			; Main.bas 8: Input "name"; s
			dw p_stdio_putstr_c, str3
			dw p_stdio_getline_c, var_s

			; Main.bas 9: Print s
			dw p_stdio_putstr_c, var_s
			dw p_stdio_newline_c

			; Main.bas 10: k$ = Inkey$
			dw p_stdio_getkey_c
			dw kw_strchr, stmp0, var_stdio_getkey_getkey
			dw kw_strcpy, var_k, stmp0

			; Main.bas 11: Print k$; Inkey
			dw p_stdio_putstr_c, var_k
			dw p_stdio_getkey_c
			dw kw_strcstr, stmp0, var_stdio_getkey_getkey
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_newline_c

			; Main.bas 12: Input "num"; n
			dw p_stdio_putstr_c, str4
			dw p_stdio_getline_c, stmp0
			dw kw_strval, stmp0, var_n

			; Main.bas 13: Print n + 1
			dw kw_addl, var_n, 1, tmp0
			dw kw_strcstr, stmp0, tmp0
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_newline_c

			; Main.bas 14: Print "lines "; StdIO.Lines
			dw p_stdio_putstr_c, str5
			dw kw_strcstr, stmp0, var_stdio_lines
			dw p_stdio_putstr_c, stmp0
			dw p_stdio_newline_c
			dw kw_printnl0
			dw p_stdio_putstr_c, str6
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub putstr (normal mode)
; ============================================================

p_stdio_putstr:

			; StdIO.cls 6: Print "<"; UCase$(s); ">";
			dw kw_strucase, stmp1, var_stdio_putstr_s
			dw kw_printstrvar, str7
			dw kw_printstrvar, stmp1
			dw kw_printstrvar, str8
			dw p_stdio_putstr_r

; ============================================================
; sub newline (normal mode)
; ============================================================

p_stdio_newline:

			; StdIO.cls 10: Print
			dw kw_printnl

			; StdIO.cls 11: Lines = Lines + 1
			dw kw_inc, var_stdio_lines
			dw p_stdio_newline_r

; ============================================================
; sub getline (normal mode)
; ============================================================

p_stdio_getline:

			; StdIO.cls 15: Input s
			dw kw_printstrvar, str9
			dw kw_inputstr, var_stdio_getline_s

			; StdIO.cls 16: s = s & "!"
			dw kw_strcat, var_stdio_getline_s, str10
			dw p_stdio_getline_r

; ============================================================
; function getkey (normal mode)
; ============================================================

p_stdio_getkey:

			; StdIO.cls 20: GetKey = 81
			dw kw_ltov, 81, var_stdio_getkey_getkey
			dw p_stdio_getkey_r

; ============================================================
; sub cls (normal mode)
; ============================================================

p_stdio_cls:

			; StdIO.cls 24: Print "[cls]"
			dw kw_printstrvar, str11
			dw kw_printnl
			dw p_stdio_cls_r

; ============================================================
; sub locate (normal mode)
; ============================================================

p_stdio_locate:

			; StdIO.cls 28: Print "[at "; x; ","; y; "]";
			dw kw_printstrvar, str12
			dw kw_printint, var_stdio_locate_x
			dw kw_printstrvar, str13
			dw kw_printint, var_stdio_locate_y
			dw kw_printstrvar, str14
			dw p_stdio_locate_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================


p_stdio_putstr_c:		; call putstr (normal)
			pop hl			; s
			ld de, var_stdio_putstr_s
			ld b, 40
p_stdio_putstr_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_stdio_putstr_si0_e
			inc hl
			inc de
			djnz p_stdio_putstr_si0
			xor a
			ld (de), a
p_stdio_putstr_si0_e:
			ld (p_stdio_putstr_rs), sp
			ld sp, p_stdio_putstr
			jp ntc_xn
p_stdio_putstr_r:		; end of putstr
			ld sp, (p_stdio_putstr_rs)
			jp ntc_xn
p_stdio_newline_c:		; call newline (normal)
			ld (p_stdio_newline_rs), sp
			ld sp, p_stdio_newline
			jp ntc_xn
p_stdio_newline_r:		; end of newline
			ld sp, (p_stdio_newline_rs)
			jp ntc_xn
p_stdio_getline_c:		; call getline (normal)
			pop hl			; s
			ld (p_stdio_getline_a0), hl
			ld de, var_stdio_getline_s
			ld b, 40
p_stdio_getline_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_stdio_getline_si0_e
			inc hl
			inc de
			djnz p_stdio_getline_si0
			xor a
			ld (de), a
p_stdio_getline_si0_e:
			ld (p_stdio_getline_rs), sp
			ld sp, p_stdio_getline
			jp ntc_xn
p_stdio_getline_r:		; end of getline
			ld de, (p_stdio_getline_a0)
			ld hl, var_stdio_getline_s
			dec de
			ld a, (de)		; the destination's capacity
			ld b, a
			inc de
p_stdio_getline_so0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_stdio_getline_so0_e
			inc hl
			inc de
			djnz p_stdio_getline_so0
			xor a
			ld (de), a
p_stdio_getline_so0_e:
			ld sp, (p_stdio_getline_rs)
			jp ntc_xn
p_stdio_getkey_c:		; call getkey (normal)
			ld hl, 0
			ld (var_stdio_getkey_getkey), hl
			ld (p_stdio_getkey_rs), sp
			ld sp, p_stdio_getkey
			jp ntc_xn
p_stdio_getkey_r:		; end of getkey
			ld sp, (p_stdio_getkey_rs)
			jp ntc_xn
p_stdio_cls_c:		; call cls (normal)
			ld (p_stdio_cls_rs), sp
			ld sp, p_stdio_cls
			jp ntc_xn
p_stdio_cls_r:		; end of cls
			ld sp, (p_stdio_cls_rs)
			jp ntc_xn
p_stdio_locate_c:		; call locate (normal)
			pop hl			; x
			ld de, var_stdio_locate_x		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; y
			ldi
			ldi
			ld (p_stdio_locate_rs), sp
			ld sp, p_stdio_locate
			jp ntc_xn
p_stdio_locate_r:		; end of locate
			ld sp, (p_stdio_locate_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
			db 40			; capacity
var_s:			ds 41
			db 40			; capacity
var_k:			ds 41
var_stdio_getkey_getkey:			dw 0
var_stdio_lines:			dw 0
p_stdio_putstr_rs:			dw 0
			db 40			; capacity
var_stdio_putstr_s:			ds 41
p_stdio_newline_rs:			dw 0
p_stdio_getline_rs:			dw 0
			db 40			; capacity
var_stdio_getline_s:			ds 41
p_stdio_getline_a0:			dw 0
p_stdio_getkey_rs:			dw 0
p_stdio_cls_rs:			dw 0
p_stdio_locate_rs:			dw 0
var_stdio_locate_x:			dw 0, 0		; parameters, one block
var_stdio_locate_y		equ var_stdio_locate_x + 2
tmp0:			dw 0
			db 40			; capacity
stmp0:			ds 41
			db 40			; capacity
stmp1:			ds 41

; numbers passed by address (read only)
lit_3:			dw 3
lit_4:			dw 4

; ============================================================
; Strings
; ============================================================

str0:			db "hello", 0
str1:			db "x", 0
str2:			db " x", 0
str3:			db "name? ", 0
str4:			db "num? ", 0
str5:			db "lines ", 0
str6:			db "Press a key", 0
str7:			db "<", 0
str8:			db ">", 0
str9:			db "? ", 0
str10:			db "!", 0
str11:			db "[cls]", 0
str12:			db "[at ", 0
str13:			db ",", 0
str14:			db "]", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_icnt @data
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_iptr @data
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done

;## ntc_d_ivar @data
ntc_ivar:		dw 0			; inputint / inkey: dest var

;## ntc_d_aptr @data
ntc_aptr:		dw 0			; atoi: text pointer

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## ntc_d_inbuf @data
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
	IF NTC_INTS					; (;@ints 0: a platform that never lets interrupts in - the Next's dot commands)
			ei
			nop					; an interrupt can be taken here
			di
	ENDIF
			ld sp, (ntc_ip)
			ret

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and DEL (or backspace). HL = buffer (its capacity in the byte
; before it), DE = where to
; jp when done (after the newline). 40 chars max, 0 terminated.
ntc_gets:
			ld (ntc_iptr), hl
			ld (ntc_ilink), de
			dec hl
			ld a, (hl)			; the buffer's capacity
			ld (ntc_icap), a
			xor a
			ld (ntc_icnt), a
ntc_gs_wait:
			ld ix, ntc_gs_key
			jp ntc_plat_getkey
ntc_gs_key:
			cp 13
			jr z, ntc_gs_done
			cp 127
			jr z, ntc_gs_del
			cp 8
			jr z, ntc_gs_del
			cp 32
			jr c, ntc_gs_wait
			ld c, a
			ld a, (ntc_icap)
			ld b, a
			ld a, (ntc_icnt)
			cp b
			jr nc, ntc_gs_wait
			inc a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			ld (hl), c
			inc hl
			ld (ntc_iptr), hl
			ld a, c
			ld ix, ntc_gs_wait
			jp ntc_plat_putc
ntc_gs_del:
			ld a, (ntc_icnt)
			or a
			jr z, ntc_gs_wait
			dec a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			dec hl
			ld (ntc_iptr), hl
			ld ix, ntc_gs_wait
			jp ntc_plat_backspace
ntc_gs_done:
			ld hl, (ntc_iptr)
			ld (hl), 0
			ld ix, (ntc_ilink)
			jp ntc_plat_newline

;## kw_inputstr ntc_gets
;kw_inputstr, <straddr>
kw_inputstr:
			pop hl
			ld de, ntc_next
			jp ntc_gets

;## ntc_atoi ntc_data
; text to number into the var at (ntc_ivar). ntc_atoi reads ntc_inbuf,
; ntc_atoi_hl reads HL. Spaces first, then - , then digits (or &H hex).
ntc_atoi:
			ld hl, ntc_inbuf
ntc_atoi_hl:
			ld a, (hl)
			cp ' '
			jr nz, ntc_atoi_sign
			inc hl
			jr ntc_atoi_hl
ntc_atoi_sign:
			ld c, 0
			cp '-'
			jr nz, ntc_atoi_amp
			inc c
			inc hl
			ld a, (hl)
ntc_atoi_amp:
			ld de, 0
			cp '&'
			jr nz, ntc_atoi_loop
			inc hl
			ld a, (hl)
			or #20
			cp 'h'
			jr nz, ntc_atoi_done
			inc hl
ntc_atoi_hex:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr c, ntc_atoi_hd
			or #20
			sub 'a' - '0'
			jr c, ntc_atoi_done
			cp 6
			jr nc, ntc_atoi_done
			add a, 10
ntc_atoi_hd:
			ex de, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			or l
			ld l, a
			ex de, hl
			inc hl
			jr ntc_atoi_hex
ntc_atoi_loop:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr nc, ntc_atoi_done
			ld (ntc_aptr), hl
			ex de, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de
			add hl, hl
			ld e, a
			ld d, 0
			add hl, de
			ex de, hl
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_atoi_loop
ntc_atoi_done:
			ld a, c
			or a
			jr z, ntc_atoi_store
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_atoi_store:
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_strchr
;kw_strchr, <dest>, <nvar>  - Chr$(n)
kw_strchr:
			pop de
			pop hl
			ld a, (hl)
			ld (de), a
			inc de
			xor a
			ld (de), a
			ret

;## kw_strcstr ntc_itoa
;kw_strcstr, <dest>, <nvar>  - number to text (CStr, "x" & n)
kw_strcstr:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld ix, ntc_next
			jp ntc_itoa

;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			pop de
			pop hl
ntc_uc_loop:
			ld a, (hl)
			cp 'a'
			jr c, ntc_uc_put
			cp 'z' + 1
			jr nc, ntc_uc_put
			sub 32
ntc_uc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_uc_loop

;## kw_strval ntc_atoi
;kw_strval, <src>, <destvar>  - Val(src): decimal or &H hex
kw_strval:
			pop hl
			pop de
			ld (ntc_ivar), de
			jp ntc_atoi_hl

;## ntc_plat_exit
; ntc_plat_exit - back to BASIC: the pages given back, its memory in slots 2-7, its
; stack, carry clear (0 OK), interrupts on - dotl_exit, in the entry's 8K
ntc_plat_exit:
			jp dotl_exit			; (in the entry's 8K: the program's own pages are unmapped on the way)

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; row (0 based)
ntc_scols:		db 32			; columns
ntc_smode:		db 1			; screen mode (nothing here: 32 columns)
			ds 128
dot_stack:						; the program's real stack (;@stack): 128 bytes, in the 8K

;## ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_putc - A = character: rst #10 on BASIC's side, the column counted (the
; ROM wraps at the edge: so does the count)
ntc_plat_putc:
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; wrapped: the ROM moved to the next row
			ld hl, ntc_cury
			inc (hl)
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - 13 (the ROM's new line)
ntc_plat_newline:
			ld a, 13
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 24
			jr c, ntc_nl_row
			ld a, 23				; (the ROM scrolls)
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_backspace - 8 (back one), space, 8 (only on the current line)
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_curx), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld a, 8
			ld (dot_ch), a
			ld hl, dot_putc
			call dot_os
			ld a, ' '
			ld (dot_ch), a
			ld hl, dot_putc
			call dot_os
			ld a, 8
			ld (dot_ch), a
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
ntc_bs_none:
			jp (ix)

;## ntc_plat_key ntc_data @shared
; ntc_plat_scankey - A = key or 0: the ROM's LAST_K after a frame (its interrupt
; scans the keyboard), the ROM's codes made the platform's: Enter 13, Delete (12)
; 127, the cursor keys (8-11) 242, 243, 241, 240; other control codes 0
ntc_plat_scankey:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_kread
			call dot_os
			ld sp, (ntc_ip)
			cp 32
			jr nc, ntc_sk_done		; a character
			cp 13
			jr z, ntc_sk_done
			cp 12
			jr nz, ntc_sk_cur
			ld a, 127				; Delete
			jr ntc_sk_done
ntc_sk_cur:
			cp 8
			jr c, ntc_sk_none
			cp 12
			jr nc, ntc_sk_none
			ld hl, ntc_sk_tab - 8
			add a, l
			ld l, a
			jr nc, ntc_sk_rd
			inc h
ntc_sk_rd:
			ld a, (hl)
			jr ntc_sk_done
ntc_sk_none:
			xor a
ntc_sk_done:
			jp (ix)
ntc_sk_tab:		db 242, 243, 241, 240	; left, right, down, up

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0


ntc_end:				; the end of the program (and of its file)
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack 0 down (the platform's)"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			ASSERT ntc_free <= #FF80, "zxndotl: the program and its arrays must end by #FF80 (the 32K at #8000, less the stack)"
